"""Morphological analyzer for the invented agglutinative language 'Voru'.

Word structure: STEM + case + number + possessive (fixed order, all optional,
each slot at most once). A parse must consume the entire word using lexicon
stems only. analyze(word) returns ALL valid parses; ambiguity is real because
some stems end in strings that look like suffixes (e.g. 'borak' ~ 'bor' + DAT).
"""

# --- Inline lexicon: 12 stems (includes 'tavel' and 'borak'; 'bor' and
# --- 'tavelos' are planted so that 'borak' and 'tavelos' are each ambiguous).
STEMS = {
    "tavel",   # required stem; makes 'tavelos' ambiguous ('tavel' + LOC)
    "borak",   # required stem; looks like 'bor' + DAT
    "bor",     # planted: makes 'borak' have 2 parses
    "tavelos", # planted: makes 'tavelos' have 2 parses ('tavel' + LOC)
    "kessu",
    "moran",
    "silvet",
    "rudan",
    "vunem",
    "ostir",
    "kalme",
    "drosi",
}

# --- Inline suffix tables, in fixed positional order ---
CASE_SUFFIXES = {"-ak": "DAT", "-el": "ACC", "-os": "LOC"}
NUMBER_SUFFIXES = {"-in": "PL"}
POSS_SUFFIXES = {"-mi": "1SG", "-sa": "2SG", "-ta": "3SG"}


def _slot_options(table):
    """Yield (suffix_string, gloss) options for one slot: empty first, then table."""
    yield "", None
    for suf, gl in table.items():
        yield suf, gl


def analyze(word):
    """Return ALL valid parses of `word` as lists [stem, GLOSS, ...].

    Each parse consumes the entire word: one lexicon stem, then an optional
    case suffix, optional number suffix, optional possessive suffix, in that
    fixed order, each slot used at most once. Results are sorted
    lexicographically for a deterministic order.
    """
    parses = set()
    for stem in sorted(STEMS):
        if not word.startswith(stem):
            continue
        rest = word[len(stem):]
        for case_suf, case_gl in _slot_options(CASE_SUFFIXES):
            if case_suf and not rest.startswith(case_suf):
                continue
            rest2 = rest[len(case_suf):]
            for num_suf, num_gl in _slot_options(NUMBER_SUFFIXES):
                if num_suf and not rest2.startswith(num_suf):
                    continue
                rest3 = rest2[len(num_suf):]
                for poss_suf, poss_gl in _slot_options(POSS_SUFFIXES):
                    if poss_suf and not rest3.startswith(poss_suf):
                        continue
                    if rest3[len(poss_suf):] != "":
                        continue  # entire word must be consumed
                    parse = [stem]
                    for gl in (case_gl, num_gl, poss_gl):
                        if gl is not None:
                            parse.append(gl)
                    parses.add(tuple(parse))
    return sorted(list(p) for p in parses)


def gloss(word):
    """Format all parses as 'stem-DAT-PL-1SG'-style strings."""
    return ["-".join(parse) for parse in analyze(word)]

